import React from 'react';
import { useLanguage } from '../context/LanguageContext';

const Stories = () => {
  const { t } = useLanguage();

  return (
    <div className="stories-page">
      <div className="page-header">
        <h1>
          <i className="fas fa-book-open"></i>
          {t('navStories', 'Histórias')}
        </h1>
        <p>{t('storiesPageDesc', 'Histórias envolventes para melhorar sua compreensão')}</p>
      </div>

      <div className="content-container">
        <div className="coming-soon">
          <i className="fas fa-tools"></i>
          <h2>{t('comingSoon', 'Em breve!')}</h2>
          <p>{t('storiesComingSoon', 'Esta página está sendo migrada para React. Em breve você terá acesso a todas as histórias interativas.')}</p>
        </div>
      </div>
    </div>
  );
};

export default Stories;
